#define GET_HIGH_WORD(h,x) ((h) = static_cast<std::uint32_t>(std::bit_cast<std::uint64_t>(double(x)) >> 32))
#define GET_LOW_WORD(l,x) ((l) = static_cast<std::uint32_t>(std::bit_cast<std::uint64_t>(double(x))))
#define EXTRACT_WORDS(h,l,x) do { GET_HIGH_WORD(h,x); GET_LOW_WORD(l,x); } while (0)
#define INSERT_WORDS(x,h,l) ((x) = std::bit_cast<double>((std::uint64_t(std::uint32_t(h)) << 32) | std::uint32_t(l)))
#define SET_HIGH_WORD(x,h) INSERT_WORDS(x,h,std::bit_cast<std::uint64_t>(double(x)))
#define SET_LOW_WORD(x,l) INSERT_WORDS(x,std::bit_cast<std::uint64_t>(double(x)) >> 32,l)
